      <SidebarMenu>
        <SidebarMenuItem>
          <SidebarMenuButton
            size="lg"
            className={agentLayoutPersonaButtonVariants({ size })}
            aria-label={`${name} — home`}
            title={`${name} — home`}
            onClick={() => {
              navigate(basePath, { replace: isOnHome });
              setSidebarOpen(false);
            }}
