              size="icon-sm"
              aria-label="Minimize to the floating chat"
              title="Minimize to the floating chat"
              data-slot="agent-conversation-minimize"
              onClick={onMinimize}
            >
              <Minimize2Icon />
            </Button>
          )}
        </div>
      </div>
    </header>
  );
}

